    # We need to check all subsets K of {0, 1, ..., n-1}
    # But there are 2^n subsets. For n=9, 2^9 = 512. This is small.
    # For n=13, 2^13 = 8192.
    # For n=15, 2^15 = 32768.
    # Let's use a recursive approach to build the sets.

    # A set K is midpoint-closed if for all x, y in K, (x+y)*inv2 % n is in K.
    inv2 = pow(2, -1, n)

    # Let's use a simpler approach. A set K is midpoint-closed if
    # it is closed under the operation f(x, y) = (x+y)*inv2 % n.
    # This is like a closure. If we start with a set S, we can find its closure.

    closures = []
    for i in range(1 << n):
        K = [j for j in range(n) if (i >> j) & 1]
        if len(K) < 3:
            continue

        # Check if K is closed
        is_closed = True
        for x in K:
            for y in K:
                z = (x + y) * inv2 % n
                if z not in K:
                    is_closed = False
                    break
            if not is_closed:
